BEGIN;

-- Fiches éditoriales du classeur joint à EPO-433. Les références 1 à 100 sont hors de ce catalogue.
CREATE TABLE non_cesu_service_candidates (
    reference INTEGER PRIMARY KEY,
    label TEXT NOT NULL UNIQUE,
    study_domain TEXT NOT NULL,
    other_study_domain TEXT,
    training_examples TEXT NOT NULL,
    family TEXT NOT NULL,
    review_point TEXT NOT NULL,
    description TEXT NOT NULL
);

CREATE TABLE offer_service_candidates (
    offer_id TEXT NOT NULL,
    service_reference INTEGER NOT NULL REFERENCES non_cesu_service_candidates(reference) ON DELETE CASCADE,
    PRIMARY KEY (offer_id, service_reference)
);


-- Les clés d’offre incluent le campus et, pour le MBA, le parcours.
-- Elles survivent au remplacement de l’annuaire Onisep. L’API vérifie que l’offre existe encore.
SELECT offers.offer_id, services.ref
FROM (VALUES
    -- Architecture intérieure et scénographie
    (ARRAY['ENS.14777:AF.130823'], ARRAY[101, 102, 103, 104, 174]),
    -- Métiers de la mode, vêtements
    (ARRAY['ENS.12403:AF.52564'], ARRAY[106, 109, 111, 112, 113, 116, 117, 118, 119, 120]),
    -- Esthétique et cosmétique
    (ARRAY['ENS.1343:AF.103675', 'ENS.25077:AF.136986', 'ENS.25077:AF.136988'], ARRAY[110]),
    -- BTS audiovisuel, image
    (ARRAY['ENS.14886:AF.82124'], ARRAY[121, 122, 123, 124, 125, 126, 138, 191, 192]),
    -- BTS audiovisuel, son
    (ARRAY['ENS.14886:AF.65118'], ARRAY[135, 136, 137, 140, 194, 195, 205]),
    -- Réalisation audiovisuelle
    (ARRAY['ENS.22809:AF.82016'], ARRAY[131, 132, 133, 134, 138, 139, 193]),
    -- Métiers du livre et de l’édition
    (ARRAY['ENS.2075:AF.14955'], ARRAY[128, 141, 142, 145, 146, 147, 148, 150, 153, 156, 157, 158, 169, 182]),
    -- Lettres
    (ARRAY['ENS.908:AF.86490'], ARRAY[141, 142, 145, 146, 147, 182]),
    -- Arts du spectacle
    (ARRAY['ENS.908:AF.56197'], ARRAY[149, 187]),
    -- Langues étrangères appliquées
    (ARRAY['ENS.14764:AF.22431', 'ENS.14764:AF.80256'], ARRAY[144, 179]),
    -- Bibliothécaire et métiers du livre
    (ARRAY['ENS.10824:AF.75234', 'ENS.6772:AF.113607'], ARRAY[129, 130, 150, 169, 170, 185]),
    -- Information numérique
    (ARRAY['ENS.6772:AF.113605'], ARRAY[130, 150, 169, 170]),
    -- Graphisme et communication graphique
    (ARRAY['ENS.12403:AF.59870', 'ENS.14777:AF.130822', 'ENS.22809:AF.9687', 'ENS.23533:AF.123616'], ARRAY[103, 128, 151, 152, 153, 154, 155, 156, 157, 159, 160, 184, 188, 196, 201, 206]),
    -- Illustration
    (ARRAY['ENS.9467:AF.99435'], ARRAY[196, 201, 203]),
    -- Réalisation de produits imprimés
    (ARRAY['ENS.12403:AF.24207'], ARRAY[151, 152, 153, 154, 156, 157, 159]),
    -- Développement web et logiciel
    (ARRAY['ENS.23533:AF.133640:full-stack', 'ENS.18914:AF.113391', 'ENS.6772:AF.112830', 'ENS.16702:AF.144182', 'ENS.19105:AF.87381', 'ENS.8917:AF.24054'], ARRAY[161, 162, 163, 164, 167]),
    -- Systèmes et réseaux
    (ARRAY['ENS.16702:AF.144170', 'ENS.19105:AF.52695', 'ENS.8917:AF.35600'], ARRAY[166, 180]),
    -- Design UX/UI
    (ARRAY['ENS.22809:AF.73521', 'ENS.23533:AF.120432'], ARRAY[165]),
    -- Communication
    (ARRAY['ENS.14886:AF.143867', 'ENS.24370:AF.44542', 'ENS.8917:AF.31027', 'ENS.6772:AF.113606'], ARRAY[168, 171, 172, 173, 187, 188, 190]),
    -- Ressources humaines
    (ARRAY['ENS.23169:AF.121551', 'ENS.23169:AF.138686'], ARRAY[181, 182, 183]),
    -- Animation socioculturelle
    (ARRAY['ENS.6772:AF.112013'], ARRAY[176, 177, 178]),
    -- Animation et création 3D
    (ARRAY['ENS.9467:AF.107722', 'ENS.9467:AF.68616', 'ENS.22809:AF.138415'], ARRAY[197]),
    -- Création de jeux vidéo
    (ARRAY['ENS.9467:AF.107722'], ARRAY[200]),
    -- Création numérique
    (ARRAY['ENS.18914:AF.113390'], ARRAY[132, 159, 196, 199]),
    -- Journalisme
    (ARRAY['ENS.1052:AF.73241', 'ENS.4137:AF.98980'], ARRAY[137, 141, 143, 147, 194])
) AS mapping(offer_ids, refs)
CROSS JOIN LATERAL unnest(mapping.offer_ids) AS offers(offer_id)
CROSS JOIN LATERAL unnest(mapping.refs) AS services(ref);

COMMIT;
